#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
# check_bad START END: the booking is refused with exit 2 and nothing is stored.
check_bad() {
  BOOKINGS=$t bash src/book.sh aoi 2026-01-05 "$1" "$2" x >/dev/null 2>&1; st=$?
  [ "$st" = 2 ] || { echo "$1-$2: exit $st, expected 2"; fail=1; }
  [ "$(grep -vc '^#' "$t")" = 0 ] || { echo "$1-$2: a rejected booking was stored"; fail=1; }
}
check_bad 9am 10:00
check_bad 09:00 10pm
rm -f "$t"; exit $fail

